<template><AppShell><view class="detail-crumb"><button class="text-button" @tap="go('home')">‹ 返回山河地图</button><button class="text-button" @tap="go('statistics')">收录说明</button></view><view class="registry-cover province-cover"><image src="/static/专题背景/人物档案纸页.png" mode="aspectFill"/><view><text class="eyebrow">山河人物 / PROVINCIAL ARCHIVE</text><text class="page-title">{{province?.name||'全国收录'}}</text><text class="muted">{{total}} 位收录人物</text></view></view><view class="filter-panel"><view class="search-field"><image src="/static/icons/search.png"/><input v-model="query" placeholder="在当前名单搜索姓名" confirm-type="search"/><button v-if="query" class="clear-button" @tap="query=''">×</button></view><picker :range="options" range-key="name" @change="select"><button class="outline">{{province?.name||'全部省份'}} ⌄</button></picker></view><view class="list-summary"><text>找到 {{items.length}} 位人物</text><text>按姓名查看资料</text></view><view v-if="items.length" class="archive-name-grid province-name-grid"><button v-for="p in items" :key="p.id" class="archive-name name-record" @tap="openPerson(p)"><text class="name-monogram">{{p.name.slice(0,1)}}</text><view class="name-record-copy"><view class="name-record-title"><text class="registry-name">{{p.name}}</text><text v-if="p.readingId" class="dossier-mark">详细档案</text></view><text class="name-date">出生 {{p.birthText||'未载'}}</text><text class="name-origin">{{p.originText||'籍贯未载'}}</text></view><text class="name-record-arrow">↗</text></button></view><StatePanel v-else title="本批资料暂无对应条目" message="未收录不代表该地区没有英雄人物。可切换省份或清除关键词。"/><view class="next-actions"><button class="primary" @tap="go('people')">阅读典型人物档案 ↗</button><button class="outline" @tap="go('assistant')">向小迹提问</button></view></AppShell></template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';import {onLoad,onShow} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import StatePanel from '../../components/StatePanel.vue';import {provinces,list} from '../../lib/全国收录.js';import {go} from '../../lib/navigation.js'
const code=ref(''),query=ref(''),options=[{code:'',name:'全部省份'},...provinces,{code:'unknown',name:'未分省人物'}],province=computed(()=>options.find(p=>p.code===code.value)),items=computed(()=>list(code.value,query.value)),total=computed(()=>list(code.value).length)
onLoad(o=>{code.value=options.some(p=>p.code===o.code)?o.code:''})
// #ifdef H5
function syncRegion(){if(!location.hash.includes('/pages/province/index'))return;const v=new URLSearchParams(location.hash.split('?')[1]||'').get('code')||'';if(options.some(p=>p.code===v)){code.value=v;query.value=''}}
onMounted(()=>window.addEventListener('hashchange',syncRegion));onBeforeUnmount(()=>window.removeEventListener('hashchange',syncRegion));onShow(syncRegion)
// #endif
const nationalCount=computed(()=>list(code.value).filter(p=>p.memberships.includes('全国名单')).length),detailAdded=computed(()=>list(code.value).filter(p=>!p.memberships.includes('全国名单')&&p.memberships.includes('详细档案')).length)
function select(e){code.value=options[Number(e.detail.value)]?.code||'';query.value=''}
function openPerson(p){const g=ipGroup(p.name);if(g)go('ip',{group:g});else p.readingId?go('person',{id:p.readingId}):go('registry',{id:p.id})}
function ipGroup(n){return ({'瞿秋白':'QQB','宋振中':'SZZ','陆定一':'LDY','江竹筠':'JZY','江姐':'JZY','马宝玉':'LYS','葛振林':'LYS','宋学义':'LYS','胡德林':'LYS','胡福才':'LYS'})[n]}
</script>
